"""Build the offline Class 3 dashboard from saved results, with Plotly embedded."""
import csv
import html
import json
from pathlib import Path
import sys
from plotly.offline import get_plotlyjs

root=Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).resolve().parents[1]
output=Path(sys.argv[2]) if len(sys.argv)>2 else root/'40_Results'/'class3_dashboard.html'
if output.exists(): raise SystemExit(f'Output exists: {output}; preserve it before rebuilding')
def js(path):
    with (root/path).open(encoding='utf-8-sig') as f: return json.load(f)
def rows(path):
    with (root/path).open(encoding='utf-8-sig',newline='') as f: return list(csv.DictReader(f))
one={r['asset']:r for r in rows('40_Results/one_year_crypto.csv')}
five={r['asset']:r for r in rows('40_Results/five_year_assets/results.csv')}
if len(one)!=40 or set(one)!=set(five): raise ValueError('Expected the same 40 crypto assets in both saved runs')
if any(r['status']!='completed' for r in list(one.values())+list(five.values())): raise ValueError('A saved asset run did not complete')
asset={name:{'one':one[name],'five':five[name]} for name in sorted(one)}
scale=rows('40_Results/cpu_scaling_one_year/summary.csv')
memory=rows('40_Results/required_results.csv')
bm=js('40_Results/numpy_btc_comparison.json')
full=js('40_Results/bitcoin_full_history.json')
rss=js('40_Results/rss_compliance/btc_full_rss.json')
env=js('40_Results/cpu_scaling_one_year/environment.json')
boundary=rows('40_Results/bitcoin_full_boundary.csv')
btc=rows('00_Instructor/Class3/data/hourly/BTCUSDT.csv')
if len(boundary)!=len(btc) or any(a['timestamp_utc'].replace('+00:00','Z')!=b['timestamp_utc'] for a,b in zip(boundary,btc)):
    raise ValueError('BTC boundary and price timestamps do not match')
payload={'assets':asset,'scale':scale,'memory':memory,'benchmark':bm,'full':full,'rss':rss,'environment':env,
         'btc':{'time':[r['timestamp_utc'] for r in btc],'price':[float(r['close']) for r in btc],
                'boundary':[float(r['boundary_usdt']) if r['boundary_usdt'] else None for r in boundary]}}
data=json.dumps(payload,separators=(',',':'),allow_nan=False).replace('</','<\\/')
template=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>American put | Class 3</title><style>
:root{--ink:#182a39;--muted:#566a79;--blue:#216a96;--green:#237766;--paper:#f4f7f8;--line:#dce5e8}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}
main{max-width:1320px;margin:auto;padding:38px 28px 65px}h1{font-size:clamp(28px,4vw,44px);line-height:1.1;margin:0 0 12px}h2{font-size:24px;margin:0 0 8px}h3{margin:0 0 8px;font-size:17px}.eyebrow{color:var(--green);font-weight:700;text-transform:uppercase;letter-spacing:.12em;font-size:12px}p{margin:8px 0;color:var(--muted)}.lead{max-width:880px;font-size:17px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:26px 0}.card,.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:19px;box-shadow:0 3px 14px #1d425009}.card strong{display:block;font-size:29px;letter-spacing:-.03em;color:var(--ink)}.card span{font-weight:650}.card small{display:block;color:var(--muted);margin-top:5px}.panel{margin-top:18px;padding:24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.chart{width:100%;height:360px}.wide-chart{height:440px}.note{font-size:13px}.tag{display:inline-block;background:#e3f1ed;color:#236a5b;border-radius:20px;padding:3px 10px;font-size:12px;font-weight:700}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px;margin-top:12px}th,td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.04em}select{border:1px solid #bacbd1;border-radius:8px;padding:9px 12px;font:inherit;background:white;color:var(--ink);min-width:190px}.selector{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.highlight{background:#eef7f5;border-left:3px solid var(--green);padding:10px 14px;border-radius:4px;margin-top:12px}.metric{font-variant-numeric:tabular-nums}details summary{cursor:pointer;font-weight:700;font-size:18px}code{font-size:13px;background:#edf3f4;padding:2px 4px;border-radius:3px}ul{color:var(--muted)}#verify{display:none}
@media(max-width:850px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.chart{height:320px}main{padding:26px 14px}.panel{padding:17px}}@media(max-width:480px){.cards{grid-template-columns:1fr 1fr}.card strong{font-size:24px}.card{padding:14px}}
</style><script>__PLOTLY__</script></head><body><main>
<header><div class="eyebrow">Algorithms in Finance · Class 3</div><h1>American put pricing<br>at scale</h1><p class="lead">A local, reproducible view of the saved Bitcoin and 40-asset experiments. Prices use an American binomial model; performance results reflect the recorded machine and workload.</p></header>
<div class="cards"><div class="card"><strong id="hero-time"></strong><span>40 assets · five years</span><small>Latest monitored batch · 8 workers</small></div><div class="card"><strong id="hero-rss"></strong><span>Peak aggregate RSS</span><small>Same five-year monitored run</small></div><div class="card"><strong id="hero-vector"></strong><span>NumPy price-only speedup</span><small>Historical A single run / B median</small></div><div class="card"><strong id="hero-parallel"></strong><span>Maximum batch speedup</span><small>Historical one-year worker scaling</small></div></div>
<section class="panel"><h2>From Python loops to NumPy</h2><p>Vectorization replaces the inner Python loop with array operations. Both versions retain O(N²) time and O(N) working memory. These are price-only measurements from separate runs, not a controlled matched benchmark.</p><div class="scroll"><table><thead><tr><th>BTC window</th><th>Version A · Python</th><th>Version B · NumPy</th><th>Indicative A / B</th><th>Numerical agreement</th></tr></thead><tbody id="optimization"></tbody></table></div><p class="note">One year: historical A single run versus the median of three B runs after warm-up. Full history: historical A single run versus a later single B RSS-monitored run. Runtimes exclude data loading and calibration; system load and monitoring differ.</p></section>
<section class="panel"><span class="tag">Historical · three batches per worker count</span><h2>Parallelization and diminishing returns</h2><p>Each batch prices the same 40 assets, including loading, calibration, worker startup and collection. Hover for efficiency and marginal speedup.</p><div class="grid"><div><h3>Median batch runtime</h3><div id="runtime" class="chart"></div></div><div><h3>Observed versus ideal speedup</h3><div id="speedup" class="chart"></div></div></div><div id="scaling-note" class="highlight"></div><p class="note">Eight workers were selected as a practical near-fastest choice before the five-year run; the slightly faster 12-worker median differs by only a few hundredths of a second. Three repetitions and a fixed configuration order do not establish a universal optimum. NumPy or its linked libraries may use internal threads.</p></section>
<section class="panel"><h2>Explore an asset</h2><p>Compare each asset’s saved one-year and full-history model. Relative premium puts prices on the same scale; raw put prices across different assets are not directly comparable.</p><div class="selector"><label for="asset">Asset</label><select id="asset"></select><span class="note">40 instructor-supplied crypto assets · in-sample calibration</span></div><div class="scroll"><table><thead><tr><th>Window</th><th>Put price</th><th>Relative premium</th><th>Periods</th><th>Log-return volatility / step</th><th>Pricing runtime</th></tr></thead><tbody id="asset-table"></tbody></table></div><p class="note">Prices are quoted in USDT per unit. One-year pricing was sequential; five-year asset timings were recorded inside an eight-worker batch and include contention. They are not a controlled timing comparison.</p></section>
<section class="panel"><span class="tag">Latest · RSS-monitored runs</span><h2>Memory and computational scaling</h2><p>The single-BTC runtimes cover pricing only. Batch runtimes include loading, calibration, worker startup and collection. RSS is observed process memory; O(N) describes algorithm working memory.</p><div class="scroll"><table><thead><tr><th>Workload</th><th>Periods per asset</th><th>Workers</th><th>Runtime</th><th>Peak aggregate RSS</th></tr></thead><tbody id="memory"></tbody></table></div><p class="note">Sampled roughly every 50 ms across the workload process and descendants. Brief peaks may be missed, and shared pages may be counted more than once. These are RSS values, not historical Python-traced allocations.</p></section>
<section class="panel"><h2>Bitcoin exercise boundary</h2><p>The boundary is the highest tree price at which immediate exercise is at least as valuable as continuation. The full-history model is calibrated and evaluated in the same window, so this is an in-sample exercise-policy comparison.</p><div id="boundary" class="chart wide-chart"></div><div id="crossing" class="highlight"></div><p class="note">One hourly observation is missing; consecutive available observations are treated as consecutive model steps. An unobserved crossing during that gap cannot be excluded.</p></section>
<section class="panel"><details><summary>Methodology and reproduction</summary><ul><li>One-year crypto windows use the last 8,761 available closes (8,760 returns); full history uses all available closes (43,822 returns per asset). The BTC prices and exercise boundaries are in sample.</li><li>Hourly log-return sample standard deviation s sets u = exp(s), d = 1/u; R = exp(0.04 T/N), q = (R − d)/(u − d), with T based on elapsed time / 365.25 days. S0 and strike are the first close.</li><li id="hardware"></li><li>Five-year workloads used eight processes. RSS sampling and differing timing boundaries are described above; previous Version A traced allocations are not RSS.</li><li>Input: <code>00_Instructor/Class3/data/hourly/</code>. Results: <code>40_Results/required_results.csv</code>, <code>40_Results/cpu_scaling_one_year/summary.csv</code>, <code>40_Results/one_year_crypto.csv</code>, <code>40_Results/five_year_assets/results.csv</code>, <code>40_Results/bitcoin_full_boundary.csv</code>.</li><li>From the lab folder, with dependencies installed: <code>python -B 20_Code/rss_compliance.py</code>, <code>python -B 20_Code/cpu_scaling.py</code>, <code>python -B 20_Code/five_year_assets.py</code>. These refuse to overwrite their existing results. Dashboard generation requires Plotly: <code>python -B 20_Code/build_dashboard.py</code>; preserve or move the existing HTML first.</li><li>See <code>README.md</code> and <code>50_Docs/REQUIRED_RESULTS.md</code> for setup and limitations. The dashboard uses only saved measurements and excludes the supplementary S&amp;P 500 dataset.</li></ul></details></section><div id="verify"></div>
</main><script>
const D=__DATA__;
const n=(x,d=2)=>Number(x).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mem=Object.fromEntries(D.memory.map(x=>[x.workload,x]));
document.getElementById('hero-time').textContent=n(mem['40 assets five years'].runtime_seconds)+' s';
document.getElementById('hero-rss').textContent=n(mem['40 assets five years'].peak_aggregate_rss_bytes/1048576)+' MiB';
document.getElementById('hero-vector').textContent=n(D.benchmark.speedup_historical_A_single_over_B_median)+'×';
document.getElementById('hero-parallel').textContent=n(Math.max(...D.scale.map(x=>Number(x.speedup))),1)+'×';
const aFull=D.full.operations.pricing, aOne=D.benchmark;
document.getElementById('optimization').innerHTML=`<tr><td>One year · N = ${aOne.N.toLocaleString()}</td><td>${n(aOne.version_A_historical_single_seconds,3)} s · single</td><td>${n(aOne.version_B_median_seconds,3)} s · median of 3</td><td>${n(aOne.speedup_historical_A_single_over_B_median)}×</td><td>Δ ${n(aOne.BTC_absolute_difference,6)} USDT</td></tr><tr><td>Full history · N = ${D.full.N.toLocaleString()}</td><td>${n(aFull.runtime_seconds,3)} s · single</td><td>${n(D.rss.runtime_seconds,3)} s · monitored single</td><td>${n(aFull.runtime_seconds/D.rss.runtime_seconds)}×</td><td>Δ ${n(Math.abs(aFull.price_usdt_per_btc-D.rss.price),6)} USDT</td></tr>`;
const workers=D.scale.map(x=>Number(x.workers)), t=D.scale.map(x=>Number(x.median_seconds)), speed=D.scale.map(x=>Number(x.speedup));
const custom=D.scale.map(x=>[Number(x.efficiency)*100,x.marginal_speedup_per_worker===''?'n/a':Number(x.marginal_speedup_per_worker).toFixed(3)]);
const config={responsive:true,displaylogo:false,modeBarButtonsToRemove:['toImage']};const layout={margin:{l:55,r:22,t:10,b:55},paper_bgcolor:'white',plot_bgcolor:'white',font:{family:'system-ui',color:'#334c5c'},xaxis:{title:{text:'Workers'},tickvals:workers,gridcolor:'#e8edef'},yaxis:{gridcolor:'#e8edef'},hovermode:'closest'};
const plots=[];
plots.push(Plotly.newPlot('runtime',[{x:workers,y:t,customdata:custom,type:'scatter',mode:'lines+markers',line:{color:'#216a96',width:3},marker:{size:8},hovertemplate:'%{x} workers<br>Median %{y:.3f} s<br>Efficiency %{customdata[0]:.1f}%<br>Marginal speedup / worker %{customdata[1]}<extra></extra>'}],{...layout,yaxis:{...layout.yaxis,title:{text:'Seconds'}}},config));
plots.push(Plotly.newPlot('speedup',[{x:workers,y:speed,customdata:custom,type:'scatter',mode:'lines+markers',name:'Observed',line:{color:'#237766',width:3},marker:{size:8},hovertemplate:'%{x} workers<br>Speedup %{y:.2f}×<br>Efficiency %{customdata[0]:.1f}%<br>Marginal speedup / worker %{customdata[1]}<extra></extra>'},{x:workers,y:workers,type:'scatter',mode:'lines',name:'Ideal linear',line:{color:'#a3b0b6',dash:'dash'},hovertemplate:'%{x} workers<br>Ideal %{y:.0f}×<extra></extra>'}],{...layout,yaxis:{...layout.yaxis,title:{text:'Speedup'}},legend:{orientation:'h',x:0,y:1.17}},config));
const s8=D.scale.find(x=>Number(x.workers)===8),s12=D.scale.find(x=>Number(x.workers)===12),s16=D.scale.find(x=>Number(x.workers)===16);
document.getElementById('scaling-note').textContent=`8 workers: ${n(s8.median_seconds,3)} s · 12 workers: ${n(s12.median_seconds,3)} s · 16 workers: ${n(s16.median_seconds,3)} s. Marginal improvement nearly disappears after 8; 16 is slower than 12 in this run.`;
const select=document.getElementById('asset');for(const name of Object.keys(D.assets))select.add(new Option(name,name));select.value='BTCUSDT';
function showAsset(){const pair=D.assets[select.value];document.getElementById('asset-table').innerHTML=[['One year',pair.one],['Full history',pair.five]].map(([label,r])=>`<tr><td>${label}</td><td>${n(r.price,4)}</td><td>${n(100*Number(r.price)/Number(r.S0),2)}%</td><td>${n(r.periods,0)}</td><td>${n(r.volatility,6)}</td><td>${n(r.pricing_seconds,3)} s</td></tr>`).join('');}select.addEventListener('change',showAsset);showAsset();
document.getElementById('memory').innerHTML=D.memory.map(r=>`<tr><td>${esc(r.workload)}</td><td>${n(r.periods_per_asset,0)}</td><td>${esc(r.workers)}</td><td>${n(r.runtime_seconds,3)} s</td><td>${n(r.peak_aggregate_rss_bytes/1048576)} MiB</td></tr>`).join('');
const c=D.full.operations.boundary.first_crossing;
plots.push(Plotly.newPlot('boundary',[{x:D.btc.time,y:D.btc.price,type:'scattergl',mode:'lines',name:'BTC close',line:{color:'#216a96',width:1},hovertemplate:'%{x}<br>BTC %{y:,.2f} USDT<extra></extra>'},{x:D.btc.time,y:D.btc.boundary,type:'scattergl',mode:'lines',name:'Exercise boundary',line:{color:'#d88b36',width:2},connectgaps:false,hovertemplate:'%{x}<br>Boundary %{y:,.2f} USDT<extra></extra>'},{x:[c.timestamp_utc],y:[c.price_usdt],type:'scatter',mode:'markers',name:'First crossing',marker:{color:'#c44b4b',size:11},hovertemplate:'%{x}<br>BTC %{y:,.2f} USDT<br>Boundary '+n(c.boundary_usdt)+' USDT<extra></extra>'}],{margin:{l:70,r:20,t:20,b:65},paper_bgcolor:'white',plot_bgcolor:'white',font:{family:'system-ui',color:'#334c5c'},xaxis:{title:{text:'Date (UTC)'},gridcolor:'#e8edef'},yaxis:{title:{text:'USDT per BTC'},gridcolor:'#e8edef'},legend:{orientation:'h',x:0,y:1.10},hovermode:'closest'},config));
document.getElementById('crossing').textContent=`First observed crossing: ${c.timestamp_utc.replace('T',' ').replace('+00:00',' UTC')} · BTC ${n(c.price_usdt)} · boundary ${n(c.boundary_usdt)} · intrinsic payoff ${n(c.intrinsic_payoff_usdt)} USDT per BTC.`;
document.getElementById('hardware').textContent=`CPU: ${D.environment.cpu_model}; ${D.environment.logical_cpus_available} logical CPUs. Python ${D.environment.python.split(' ')[0]}; NumPy ${D.environment.numpy}.`;
Promise.all(plots).then(()=>{document.body.dataset.dashboardReady='true';if(location.hash==='#verify'){select.value=Object.keys(D.assets).at(-1);select.dispatchEvent(new Event('change'));Plotly.Fx.hover('runtime',[{curveNumber:0,pointNumber:0}]);setTimeout(()=>{document.getElementById('verify').textContent=JSON.stringify({assets:select.options.length,last:select.value,table:document.getElementById('asset-table').textContent,charts:['runtime','speedup','boundary'].map(x=>document.getElementById(x).data.length),hover:document.querySelectorAll('.hovertext').length});},500);}});
</script></body></html>'''
document=template.replace('__PLOTLY__',get_plotlyjs()).replace('__DATA__',data)
output.parent.mkdir(parents=True,exist_ok=True)
with output.open('x',encoding='utf-8') as f: f.write(document)
print(f'Created {output}; {len(asset)} assets, {len(btc)} BTC observations.')
